        const auto normal=folder(L"normal");auto scope=std::make_shared<Scope>(normal);const auto fixture=hooks();auto connected=ensure_native_host_fixture(options(scope),fixture);check(connected.ready()&&connected.authenticated&&connected.spawned&&connected.disposition==D::ready_started&&connected.ownership==Ownership::owned,"A free scope may start only its exact owned host and authenticate before reporting readiness");check(connected.scope->id()==scope->id()&&connected.expected_image==file_identity(fixture_executable)&&connected.sessions.empty()&&spawns==1,"Readiness must retain physical scope/exact image and never create a provider session");Client client(scope,connected.expected_image,std::chrono::milliseconds(250));check(client.list().empty(),"The connection helper must only list an empty host, never start provider setup");
