        const auto crash_path=folder(L"spawn-failure");auto crash_scope=std::make_shared<Scope>(crash_path);auto failed=fixture;std::atomic<unsigned> failed_calls{};failed.spawn=[&](const auto&,const auto&,const auto&){++failed_calls;auto lifetime=std::make_shared<int>(1);return NativeHostFixtureChild{lifetime,[]{return false;}};};const auto crashed=ensure_native_host_fixture(options(crash_scope),failed);check(crashed.disposition==D::start_failed&&crashed.spawned&&!crashed.ready()&&failed_calls==1&&ownership(*crash_scope)==Ownership::free,"A failed trusted spawn must report failure once without retrying a process or claiming ownership");
